    test("GetTldRequirementsV2 (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new NamecomClient({
            maxRetries: 0,
            username: "test",
            password: "test",
            environment: server.baseUrl,
        });

        const rawResponseBody = {
            $schema: "http://json-schema.org/draft-07/schema#",
            type: "object",
            title: ".it Domain Registration Requirements Schema",
            description: "Registration requirements for .it domains",
            properties: {
                tldInfo: {
                    tld: ".it",
                    ccTld: true,
                    supportsTransferLock: true,
                    supportsDnssec: true,
                    supportsPremium: false,
                    supportsPrivacy: false,
                    supportsInternalTransfer: true,
                    requiresPreDelegation: false,
                    expirationGracePeriod: 25,
                    allowedRegistrationYears: [1, 3, 5, 8, 10],
                    idnLanguages: { IT: "Italian" },
                    hsts: false,
                    minDomainLength: 3,
                    minIdnDomainLength: 5,
                    registryOperator: "nic.it",
                    claimsCheckRequired: ["registration"],
                    requireIdnSld: false,
                },
                contacts: {
                    type: "object",
                    properties: {
                        registrant: {
                            type: "object",
                            properties: {
                                firstName: {
                                    type: "string",
                                    title: "First Name",
                                    description: "First name of registrant contact",
                                },
                                email: {
                                    type: "string",
                                    format: "email",
                                    title: "Email",
                                    description: "Email address of registrant contact",
                                },
                            },
                            required: ["firstName", "email"],
                        },
                    },
                    required: ["registrant"],
                },
                tldRequirements: {
                    type: "object",
                    properties: {
                        "X-IT-ENTITY-TYPE": {
                            type: "string",
                            title: "Registrant Entity Type",
                            enum: ["1", "2", "3", "4", "5", "6", "7"],
                        },
                        "X-IT-PIN": {
                            type: "string",
                            title: ".IT PIN number",
                            description:
                                "16 alphanumeric characters (tax code) for natural persons or 11 digits (VAT number) for organizations",
                        },
                    },
                },
            },
            required: ["tldInfo", "contacts", "tldRequirements"],
            allOf: [{ key: "value" }],
            if: { key: "value" },
            then: { key: "value" },
            else: { key: "value" },
        };

        server
            .mockEndpoint()
            .get("/core/v1/domaininfo/requirementsV2/fr")
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.domainInfo.getTldRequirementsV2({
            tld: "fr",
        });
        expect(response).toEqual(rawResponseBody);
    });

